# Reduce each term of x^2024 + x + 1 modulo x^2 - 1 (where x^2 = 1).
# x^n reduces to 1 when n is even and to x when n is odd.
const, lin = 0, 0
for power, coeff in [(2024, 1), (1, 1), (0, 1)]:
    if power % 2 == 0:
        const += coeff
    else:
        lin += coeff
print(("x" if lin == 1 else f"{lin}x") + f"+{const}")

from fractions import Fraction
from itertools import product
def P(x):
    return 2*x**3 - 3*x**2 - 11*x + 6
p_divs = [1, 2, 3, 6]
q_divs = [1, 2]
roots = set()
for p, q in product(p_divs, q_divs):
    for sgn in (1, -1):
        c = Fraction(sgn * p, q)
        if P(c) == 0:
            roots.add(c)
print(sum(roots))

import cmath
# Durand-Kerner iteration for the roots of x^3 - 2x + 5
coeffs = [1, 0, -2, 5]
def P(z):
    v = 0
    for c in coeffs:
        v = v * z + c
    return v
z = [complex(0.4, 0.9) ** k for k in range(3)]
for _ in range(500):
    new = []
    for i in range(3):
        denom = 1
        for j in range(3):
            if j != i:
                denom *= (z[i] - z[j])
        new.append(z[i] - P(z[i]) / denom)
    z = new
total = sum(r * r for r in z)
print(round(total.real))

# (1+i)^3 + a(1+i) + b = 0 must hold exactly for integers a, b.
found = []
for a in range(-10, 11):
    for b in range(-10, 11):
        z = 1 + 1j
        if z**3 + a * z + b == 0:
            found.append((a, b))
print(found[0][0] + found[0][1])

